function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is a whole number from 1 to 100000.';
  if (!Number.isInteger(k) || k < n || k > 26 * n) return 'k must be between n and 26 * n.';
  return null;
}

