function getSmallestString(n, k) {
  const chars = new Array(n);
  let remaining = k;

  for (let i = n - 1; i >= 0; i--) {
    const value = Math.min(26, remaining - i);
    chars[i] = String.fromCharCode(96 + value);
    remaining -= value;
  }
  return chars.join('');
}

