function getSmallestString(n, k) {
  // Fill from the front, choosing the smallest letter that still lets the rest reach the total.
  let result = '';
  let left = k;
  for (let pos = 0; pos < n; pos++) {
    const after = n - pos - 1;
    for (let c = 1; c <= 26; c++) {
      const rest = left - c;
      if (rest >= after && rest <= 26 * after) {
        result += String.fromCharCode(96 + c);
        left = rest;
        break;
      }
    }
  }
  return result;
}

