function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 8);
  const pick = rand();
  let k;
  if (pick < 0.1) k = n;
  else if (pick < 0.2) k = 26 * n;
  else if (pick < 0.35) k = n + Math.floor(rand() * 30);
  else k = n + Math.floor(rand() * (25 * n + 1));
  return [n, Math.min(k, 26 * n)];
}
